import fs from 'node:fs';
import {createHash} from 'node:crypto';

// Generated by a separate native Xiaohe TTS connection. Never inject SayHello
// into a session that is awaiting a function result: it can replace that turn.
let clips;
export function loadToolStartClips() {
  if(clips)return clips;
  const root=new URL('./assets/',import.meta.url);
  const manifest=JSON.parse(fs.readFileSync(new URL('tool-start-provenance.json',root),'utf8'));
  if(manifest.provider!=='seeduplex'||manifest.voice!=='xiaohe'||manifest.sampleRate!==24000||manifest.format!=='pcm16le')throw Error('Invalid tool notice audio format');
  const loaded={};
  for(const key of ['memory','web','other']){
    const spec=manifest.clips[key],pcm=fs.readFileSync(new URL(`tool-start-${key}.pcm`,root));
    if(!spec?.text||pcm.length!==spec.bytes||pcm.length%2||createHash('sha256').update(pcm).digest('hex')!==spec.sha256)throw Error('Tool notice audio hash mismatch');
    loaded[key]={...spec,pcm,sampleRate:24000,source:'cached-native-tool-start'};
  }
  clips=loaded;return clips;
}
export function toolStartClip(call,loaded=loadToolStartClips()) {
  if(['end_call','cancel_task','delegate_to_v','process','show_content','set_speaker_volume','look'].includes(call.name))return null;
  const name=call.name==='openclaw_tool'?call.args?.tool:call.name;
  if(['end_call','cancel_task','delegate_to_v','process','show_content'].includes(name))return null;
  return loaded[name==='memory_search'?'memory':['web_search','web_fetch'].includes(name)?'web':'other'];
}

// Said while a slow tool is still running. Like the start notice it is host-owned
// PCM, never SayHello: injected TTS during a native wait can lose the result.
export const TOOL_PROGRESS_LINES = ['还在查，稍等一下。','这个查得有点久，马上就好。','还在等结果，再给我一点时间。'];
let progressClips;
/** Validated progress clips, or none until scripts/generate-notice-clips.mjs has made them. */
export function loadToolProgressClips(root) {
  if(!root)return progressClips??=loadToolProgressClips(new URL('./assets/',import.meta.url));
  let manifest;
  try{manifest=JSON.parse(fs.readFileSync(new URL('tool-progress-provenance.json',root),'utf8'));}
  catch(error){if(error.code==='ENOENT')return [];throw error;}
  if(manifest.provider!=='seeduplex'||manifest.voice!=='xiaohe'||manifest.sampleRate!==24000||manifest.format!=='pcm16le')throw Error('Invalid tool progress audio format');
  return TOOL_PROGRESS_LINES.map((text,i)=>{
    const key=`progress-${i+1}`,spec=manifest.clips?.[key],pcm=fs.readFileSync(new URL(`tool-${key}.pcm`,root));
    if(spec?.text!==text||pcm.length!==spec.bytes||pcm.length%2||createHash('sha256').update(pcm).digest('hex')!==spec.sha256)throw Error('Tool progress audio hash mismatch');
    return {...spec,pcm,sampleRate:24000,source:'cached-native-tool-progress'};
  });
}
